typedef float rational_t;

#define assert(exp) ((void)0)
extern "C" float fabsf(float);
#define fabs(x) fabsf(x)

class vector3d
{
public:
  typedef rational_t T;
  T x,y,z;

  inline vector3d() {}
  inline vector3d(const vector3d& v) { x = v.x; y = v.y; z = v.z; }
  inline vector3d(T _x, T _y, T _z) { x = _x; y = _y; z = _z; }

  inline vector3d& operator = (const vector3d& v)
  { x = v.x; y = v.y; z = v.z; return *this; }

  inline vector3d& operator += (const vector3d& v)
  { x += v.x; y += v.y; z += v.z; return *this; }
};

inline vector3d operator * (const vector3d& a, vector3d::T d)
{ return vector3d(d * a.x, d * a.y, d * a.z); }

inline vector3d operator / (const vector3d& a, vector3d::T d)
{
  assert(d != 0.0f);
  vector3d::T d_inv = 1.0f/d;
  return vector3d(a.x*d_inv, a.y*d_inv, a.z*d_inv);
}

class SimpleForce
{
public:
  void SetForceScalar(float scalar) { s = scalar;}

  vector3d dir;
  float s;
};

class PhysicsObjectClass
{
public:
  float mass;
  char released_layout[0x6C];
  vector3d linMom;
};

class SurfBoardObjectClass
{
public:
  float props_forwardForce;
  PhysicsObjectClass *rb;
  SimpleForce forward;
  char released_layout[0xA98];
  vector3d lip_vec;

  void MoveForwardOnX(float degree);
};

//  useful for tubes, this changes player velocity, but only along the X-axis.
void SurfBoardObjectClass::MoveForwardOnX(float degree)
{
//	int current_beach = g_game_ptr->get_beach_id ();

	forward.SetForceScalar(props_forwardForce * degree);

	//  Set the surfer at normal speed based on his direction.
	vector3d vel = this->rb->linMom / this->rb->mass;

	//  No left/right or up/down.
	vel.x *= fabs(lip_vec.x);
	vel.y *= fabs(lip_vec.y);
	vel.z *= fabs(lip_vec.z);

	rb->linMom = vel*this->rb->mass;
	rb->linMom += forward.dir * forward.s;
}
